class Solution {
    public int maxSubArray(int[] nums) {
        int current = nums[0];
        int best = nums[0];
        for (int i = 1; i < nums.length; i++) {
            current = Math.max(nums[i], current + nums[i]);
            best = Math.max(best, current);
        }
        return best;
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        int[] dp = new int[nums.length];
        dp[0] = nums[0];
        int best = dp[0];
        for (int i = 1; i < nums.length; i++) {
            dp[i] = Math.max(nums[i], dp[i - 1] + nums[i]);
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        int prefix = 0;
        int minPrefix = 0;
        int best = Integer.MIN_VALUE;
        for (int num : nums) {
            prefix += num;
            best = Math.max(best, prefix - minPrefix);
            minPrefix = Math.min(minPrefix, prefix);
        }
        return best;
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        return solve(nums, 0, nums.length - 1);
    }

    private int solve(int[] nums, int left, int right) {
        if (left == right) {
            return nums[left];
        }
        int mid = left + (right - left) / 2;
        int leftBest = solve(nums, left, mid);
        int rightBest = solve(nums, mid + 1, right);

        int sum = 0;
        int bestLeftSuffix = Integer.MIN_VALUE;
        for (int i = mid; i >= left; i--) {
            sum += nums[i];
            bestLeftSuffix = Math.max(bestLeftSuffix, sum);
        }
        sum = 0;
        int bestRightPrefix = Integer.MIN_VALUE;
        for (int i = mid + 1; i <= right; i++) {
            sum += nums[i];
            bestRightPrefix = Math.max(bestRightPrefix, sum);
        }
        int crossing = bestLeftSuffix + bestRightPrefix;
        return Math.max(Math.max(leftBest, rightBest), crossing);
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        State result = single(nums[0]);
        for (int i = 1; i < nums.length; i++) {
            result = merge(result, single(nums[i]));
        }
        return result.best;
    }

    private State single(int value) {
        return new State(value, value, value, value);
    }

    private State merge(State left, State right) {
        int total = left.total + right.total;
        int prefix = Math.max(left.prefix, left.total + right.prefix);
        int suffix = Math.max(right.suffix, right.total + left.suffix);
        int best = Math.max(Math.max(left.best, right.best), left.suffix + right.prefix);
        return new State(total, prefix, suffix, best);
    }

    private static class State {
        final int total;
        final int prefix;
        final int suffix;
        final int best;

        State(int total, int prefix, int suffix, int best) {
            this.total = total;
            this.prefix = prefix;
            this.suffix = suffix;
            this.best = best;
        }
    }
}
